/* ============================================================
   Margin — Issue 14, “Low Water”
   Print-editorial landing page. Local system fonts only.
   ============================================================ */

/* ---------- Tokens ---------- */

:root {
  --paper: #F6F1E7;
  --paper-deep: #EDE4D0;
  --ghost-num: #E7DCC3;
  --ink: #1C1812;
  --ink-soft: #5B5346;
  --hair: rgba(28, 24, 18, 0.25);
  --river: #2C5A50;
  --rust: #8C2D12;

  --serif: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, "DejaVu Sans Mono", monospace;

  --text: 1.0625rem;
  --lh: 1.65;
  --measure: 36rem;
  --gap: clamp(4.5rem, 10vw, 8rem);
  --pad: clamp(1.15rem, 5vw, 4.5rem);
  --max: 74rem;
}

html.reading-mode {
  --text: 1.25rem;
  --lh: 1.9;
  --measure: 41rem;
  --gap: clamp(5.5rem, 11vw, 9rem);
}

/* ---------- Base ---------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--serif);
  font-size: var(--text);
  line-height: var(--lh);
}

p {
  margin: 0;
}

h1, h2, h3 {
  margin: 0;
  font-weight: 400;
}

a {
  color: inherit;
}

img, svg {
  max-width: 100%;
}

::selection {
  background: var(--river);
  color: var(--paper);
}

:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 3px;
}

.wrap {
  max-width: var(--max);
  margin-inline: auto;
  padding-inline: var(--pad);
}

.section {
  margin-top: var(--gap);
  scroll-margin-top: 3rem;
}

/* ---------- Utility ---------- */

.skip {
  position: absolute;
  top: -4rem;
  left: 1rem;
  z-index: 20;
  padding: 0.7rem 1.2rem;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--mono);
  font-size: 0.8rem;
  text-decoration: none;
  transition: top 0.2s ease;
}

.skip:focus {
  top: 1rem;
}

.sr-status {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.label,
.gauge-tag,
.byline,
.note,
.kicker,
.meta-issue,
.tagline,
.arc-no,
.arc-meta,
.field-label,
.form-hint,
.form-feedback,
.footer-meta,
.to-top,
.mode-toggle,
.entry-no {
  font-family: var(--mono);
}

/* ---------- Reveal (progressive enhancement) ---------- */

html.js .reveal {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity 0.65s ease, transform 0.65s ease;
}

html.js .reveal.is-in {
  opacity: 1;
  transform: none;
}

/* ---------- Masthead ---------- */

.masthead {
  border-top: 5px solid var(--ink);
  padding-top: 1.4rem;
}

.masthead-top {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.wordmark {
  font-size: clamp(2.4rem, 9vw, 5.2rem);
  line-height: 1;
  letter-spacing: 0.24em;
  text-transform: uppercase;
}

.tagline {
  margin-top: 0.2rem;
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-soft);
  line-height: 1.7;
}

.masthead-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem 1.5rem;
  margin-top: 1.3rem;
  padding-block: 0.8rem;
  border-top: 4px double var(--ink);
  border-bottom: 1px solid var(--ink);
}

.meta-issue {
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.mode-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.65em;
  padding: 0.5em 1em;
  border: 1px solid var(--ink);
  background: transparent;
  color: var(--ink);
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background-color 0.2s ease, color 0.2s ease;
}

.mode-toggle:hover {
  background: rgba(28, 24, 18, 0.07);
}

.mode-dot {
  width: 0.55em;
  height: 0.55em;
  border: 1px solid currentColor;
  border-radius: 50%;
  flex: none;
}

.mode-toggle[aria-pressed="true"] {
  background: var(--ink);
  color: var(--paper);
}

.mode-toggle[aria-pressed="true"] .mode-dot {
  background: var(--paper);
  border-color: var(--paper);
}

/* ---------- Hero ---------- */

.hero {
  display: grid;
  gap: clamp(2rem, 6vw, 4rem);
  margin-top: clamp(3rem, 7vw, 5.5rem);
  scroll-margin-top: 3rem;
}

.kicker {
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--river);
  margin-bottom: 1.1rem;
}

.hero h1 {
  font-size: clamp(4.1rem, 14vw, 10rem);
  line-height: 0.94;
  letter-spacing: -0.015em;
}

.hero h1 .t2 {
  font-style: italic;
}

.issue-meta {
  margin-top: 1.4rem;
  font-size: 0.95rem;
  font-style: italic;
  color: var(--ink-soft);
  max-width: 34ch;
}

.hero-art {
  max-width: 34rem;
}

.hero-svg {
  display: block;
  width: 100%;
  height: auto;
}

.hero-svg .c-line {
  fill: none;
  stroke: var(--ink);
  stroke-width: 1.4;
}

.hero-svg .g-ax {
  stroke: var(--ink);
  stroke-width: 1.2;
}

.hero-svg .g-tick {
  stroke: var(--ink);
  stroke-width: 1.2;
}

.hero-svg .g-label {
  font-family: var(--mono);
  font-size: 11px;
  fill: var(--ink-soft);
  letter-spacing: 0.06em;
}

.hero-svg .lwm {
  fill: none;
  stroke: var(--rust);
  stroke-width: 1.4;
  stroke-dasharray: 7 5;
}

.hero-svg .lwm-label {
  font-family: var(--mono);
  font-size: 10px;
  fill: var(--rust);
  letter-spacing: 0.18em;
}

.hero-svg .xmark {
  fill: none;
  stroke: var(--ink);
  stroke-width: 1.2;
}

.hero-svg .cap {
  fill: var(--paper);
  stroke: var(--ink);
  stroke-width: 1.4;
}

.hero-svg .plan {
  fill: none;
  stroke: var(--ink-soft);
  stroke-width: 1.1;
  stroke-dasharray: 4 3;
}

/* ---------- Contents ---------- */

.contents {
  margin-top: clamp(3rem, 7vw, 5rem);
  border-top: 4px double var(--ink);
  padding-top: 1.3rem;
}

.contents .label {
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ink-soft);
  margin-bottom: 1rem;
}

.contents ol {
  margin: 0;
  padding: 0;
  list-style: none;
  counter-reset: contents;
}

.contents li {
  counter-increment: contents;
}

.contents li + li {
  margin-top: 0.75rem;
}

.contents a {
  display: flex;
  align-items: baseline;
  gap: 0.6rem;
  padding-block: 0.35rem;
  font-size: clamp(1.05rem, 2.4vw, 1.3rem);
  line-height: 1.35;
  text-decoration: underline;
  text-decoration-color: rgba(44, 90, 80, 0.4);
  text-underline-offset: 0.3em;
}

.contents a::before {
  content: counter(contents, decimal-leading-zero);
  font-family: var(--mono);
  font-size: 0.75em;
  color: var(--river);
  letter-spacing: 0.08em;
  flex: none;
}

.contents a:hover {
  text-decoration-color: var(--river);
}

.contents .leader {
  flex: 1 1 auto;
  min-width: 1.5rem;
  border-bottom: 1px dotted rgba(28, 24, 18, 0.55);
  transform: translateY(-0.3em);
}

.contents .who {
  flex: none;
  font-family: var(--mono);
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

/* ---------- Gauge divider (section motif) ---------- */

.gauge {
  display: flex;
  align-items: flex-end;
  gap: 1.25rem;
  margin-bottom: clamp(1.8rem, 4vw, 3rem);
}

.gauge::after {
  content: "";
  flex: 1 1 auto;
  height: 8px;
  border-top: 1px solid var(--ink);
  background: repeating-linear-gradient(
    to right,
    rgba(28, 24, 18, 0.4) 0 1px,
    transparent 1px 10px
  );
}

.gauge-tag {
  flex: none;
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  padding-bottom: 3px;
}

/* ---------- Cover story ---------- */

.sec-title {
  font-size: clamp(1.8rem, 4.5vw, 2.7rem);
  line-height: 1.05;
  margin-bottom: 2rem;
}

.cover-grid {
  display: grid;
  gap: 2.2rem;
}

.cover-head h2 {
  font-size: clamp(2.5rem, 8vw, 5rem);
  line-height: 1;
  letter-spacing: -0.01em;
}

.cover-head h2 em {
  font-style: italic;
}

.byline {
  margin-top: 1.1rem;
  font-size: 0.75rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.lede {
  max-width: 34rem;
  text-align: justify;
  hyphens: auto;
  line-height: 1.7;
  font-size: calc(var(--text) * 1.12);
}

.lede::first-letter {
  float: left;
  font-size: 3em;
  line-height: 0.84;
  padding: 0.05em 0.14em 0 0;
  color: var(--river);
}

.note {
  margin-top: 1.6rem;
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.pull {
  margin: 0;
}

.pull p {
  font-size: clamp(1.45rem, 3.5vw, 2rem);
  font-style: italic;
  line-height: 1.3;
}

.pull p::before {
  content: "\201C";
}

.pull p::after {
  content: "\201D";
}

.pull-src {
  margin-top: 0.9rem;
  font-family: var(--mono);
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rust);
}

/* ---------- Story index ---------- */

.index {
  margin: 0;
  padding: 0;
  list-style: none;
}

.entry {
  display: grid;
  gap: 1rem;
  padding-block: clamp(1.6rem, 4vw, 2.4rem);
  border-top: 1px solid var(--ink);
  scroll-margin-top: 3.5rem;
}

.entry:last-child {
  border-bottom: 1px solid var(--ink);
}

.entry-no {
  font-size: 0.8rem;
  letter-spacing: 0.14em;
  color: var(--river);
}

.entry h3 {
  font-size: clamp(1.7rem, 4.5vw, 2.2rem);
  line-height: 1.08;
}

.entry .byline {
  margin-top: 0.55rem;
}

.entry-summary {
  max-width: min(100%, var(--measure));
  color: var(--ink-soft);
  line-height: 1.7;
}

/* ---------- Archive strip ---------- */

.archive {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 1.6rem;
}

.archive li {
  border-left: 1px solid var(--ink);
  padding-left: 1.1rem;
}

.arc-no {
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--river);
}

.arc-title {
  margin-top: 0.5rem;
  font-size: 1.35rem;
  line-height: 1.15;
}

.arc-meta {
  margin-top: 0.55rem;
  font-size: 0.68rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.st-ok {
  color: var(--river);
}

.st-low {
  color: var(--ink);
}

.st-out {
  color: var(--rust);
}

/* ---------- Subscribe ---------- */

.subscribe {
  position: relative;
}

.ghost {
  position: absolute;
  right: -0.06em;
  bottom: -0.18em;
  font-size: clamp(13rem, 30vw, 24rem);
  line-height: 0.7;
  color: var(--ghost-num);
  z-index: 0;
  pointer-events: none;
  user-select: none;
}

html.reading-mode .ghost {
  opacity: 0.4;
}

.sub-grid {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 3rem;
}

.sub-copy h2 {
  font-size: clamp(2.1rem, 6vw, 3.4rem);
  line-height: 1.04;
  letter-spacing: -0.01em;
}

.sub-para {
  margin-top: 1.4rem;
  max-width: 42ch;
  line-height: 1.7;
}

.terms {
  margin: 2rem 0 0;
}

.terms > div {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1.5rem;
  padding-block: 0.85rem;
  border-top: 1px solid var(--hair);
}

.terms dt {
  font-family: var(--mono);
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--river);
}

.terms dd {
  margin: 0;
  font-size: 1.05rem;
  text-align: right;
}

/* --- Form --- */

.form-title {
  font-size: 1.35rem;
  margin-bottom: 1.4rem;
}

.field-label {
  display: block;
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-soft);
  margin-bottom: 0.8rem;
}

.input {
  width: 100%;
  font-family: var(--mono);
  font-size: 1rem;
  color: var(--ink);
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--ink);
  border-radius: 0;
  padding: 0.65em 0;
  outline: none;
  transition: box-shadow 0.15s ease;
}

.input:focus {
  box-shadow: 0 1px 0 0 var(--river);
}

.input[aria-invalid="true"] {
  border-bottom-color: var(--rust);
  box-shadow: 0 1px 0 0 var(--rust);
}

.input[readonly] {
  color: var(--ink-soft);
}

.form-hint {
  margin-top: 0.9rem;
  font-size: 0.7rem;
  letter-spacing: 0.08em;
  line-height: 1.6;
  color: var(--ink-soft);
  max-width: 34ch;
}

.btn {
  margin-top: 1.7rem;
  font-family: var(--mono);
  font-size: 0.78rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--ink);
  padding: 0.85em 1.5em;
  cursor: pointer;
  transition: background-color 0.2s ease, color 0.2s ease, transform 0.1s ease;
}

.btn:hover {
  background: var(--ink);
  color: var(--paper);
}

.btn:active {
  transform: translateY(1px);
}

.btn:disabled {
  background: var(--paper-deep);
  color: var(--ink-soft);
  border-color: rgba(28, 24, 18, 0.35);
  cursor: default;
}

.form-feedback {
  margin-top: 1.2rem;
  font-size: 0.8rem;
  line-height: 1.6;
  min-height: 3.4em;
  max-width: 40ch;
}

.form-feedback.error {
  color: var(--rust);
}

.form-feedback.ok {
  color: var(--river);
}

/* ---------- Footer ---------- */

.footer {
  margin-top: var(--gap);
  border-top: 4px double var(--ink);
  padding-block: 1.8rem 3rem;
}

.footer-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.6rem 3rem;
}

.footer-word {
  font-style: italic;
  max-width: 44ch;
}

.footer-meta {
  font-size: 0.68rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.footer-base {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: baseline;
  gap: 0.5rem 3rem;
  margin-top: 2.2rem;
  font-family: var(--mono);
  font-size: 0.66rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.to-top {
  text-decoration: underline;
  text-underline-offset: 0.3em;
  letter-spacing: 0.12em;
}

/* ---------- Reading mode ---------- */

html.reading-mode .hero-svg {
  opacity: 0.35;
}

html.reading-mode .lede,
html.reading-mode .entry-summary,
html.reading-mode .sub-para {
  max-width: min(100%, var(--measure));
}

/* ---------- Responsive ---------- */

@media (min-width: 720px) {
  .masthead-top {
    flex-direction: row;
    justify-content: space-between;
    align-items: flex-end;
  }

  .tagline {
    text-align: right;
    margin-top: 0;
  }

  .entry {
    grid-template-columns: 4ch minmax(0, 1fr) minmax(0, 1.1fr);
    gap: clamp(1.5rem, 4vw, 3rem);
  }

  .entry-no {
    padding-top: 0.5rem;
  }

  .archive {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .footer-grid,
  .footer-base {
    flex-wrap: nowrap;
  }
}

@media (min-width: 880px) {
  .hero {
    grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
    align-items: start;
  }

  .hero-art {
    justify-self: end;
    margin-top: 1.5rem;
    margin-bottom: -2.5rem;
    max-width: none;
  }

  .cover-grid {
    grid-template-columns: repeat(12, 1fr);
    gap: 2.2rem;
  }

  .cover-head {
    grid-column: 1 / span 7;
  }

  .cover-body {
    grid-column: 3 / span 6;
    margin-top: 1rem;
  }

  .pull {
    grid-column: 10 / span 3;
    grid-row: 1 / span 2;
    align-self: end;
    justify-self: end;
    text-align: right;
    max-width: 18rem;
  }

  .entry:nth-child(2) {
    padding-left: 8%;
  }

  .entry:nth-child(3) {
    padding-left: 16%;
  }

  .sub-grid {
    grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
    gap: clamp(3rem, 6vw, 5rem);
  }

  .sub-form {
    border-left: 1px solid var(--ink);
    padding-left: clamp(2rem, 4vw, 3.5rem);
  }
}

/* Ledger margin line: appears once the page has room to spare. */
@media (min-width: 1180px) {
  body::before {
    content: "";
    position: fixed;
    inset-block: 0;
    left: calc(50% - var(--max) / 2 - 4.5rem);
    width: 0;
    border-left: 2px solid var(--rust);
    pointer-events: none;
  }
}

/* ---------- Motion preferences ---------- */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  html.js .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }

  .btn,
  .mode-toggle,
  .input {
    transition: none;
  }
}

/* ---------- Print ---------- */

@media print {
  body {
    background: #fff;
  }

  .mode-toggle,
  .sub-form,
  .hero-svg,
  .ghost {
    display: none;
  }

  html.js .reveal {
    opacity: 1;
    transform: none;
  }
}

/* Margin — Issue 14 · Low Water
   Reading-mode control, gentle reveals, and a local-only
   reservation form. No network requests anywhere. */

(function () {
  "use strict";

  var root = document.documentElement;
  root.classList.add("js");

  var STORAGE_KEY = "margin.reading-mode";
  var prefersReduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function safeGet(key) {
    try {
      return window.localStorage.getItem(key);
    } catch (err) {
      return null;
    }
  }

  function safeSet(key, value) {
    try {
      window.localStorage.setItem(key, value);
    } catch (err) {
      /* Storage unavailable — the toggle still works for this visit. */
    }
  }

  /* ---- Reading mode ---- */

  var modeToggle = document.getElementById("reading-toggle");
  var modeStatus = document.getElementById("mode-status");

  function applyReadingMode(on) {
    root.classList.toggle("reading-mode", on);
    if (modeToggle) {
      modeToggle.setAttribute("aria-pressed", on ? "true" : "false");
      var label = modeToggle.querySelector(".mode-label");
      if (label) {
        label.textContent = on ? "Reading mode \u00B7 on" : "Reading mode";
      }
    }
    if (modeStatus) {
      modeStatus.textContent = on
        ? "Reading mode on. Type is larger and spacing is calmer."
        : "Reading mode off. Standard layout restored.";
    }
  }

  if (safeGet(STORAGE_KEY) === "on") {
    applyReadingMode(true);
  }

  if (modeToggle) {
    modeToggle.addEventListener("click", function () {
      var on = !root.classList.contains("reading-mode");
      applyReadingMode(on);
      safeSet(STORAGE_KEY, on ? "on" : "off");
    });
  }

  /* ---- Gentle reveals ---- */

  var revealItems = Array.prototype.slice.call(document.querySelectorAll(".reveal"));

  if (prefersReduced || !("IntersectionObserver" in window)) {
    revealItems.forEach(function (el) {
      el.classList.add("is-in");
    });
  } else {
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-in");
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.08, rootMargin: "0px 0px -24px 0px" }
    );
    revealItems.forEach(function (el) {
      io.observe(el);
    });
  }

  /* ---- Reservation form (inline validation, nothing is submitted) ---- */

  var form = document.getElementById("reserve-form");
  var emailInput = document.getElementById("email");
  var feedback = document.getElementById("form-feedback");
  var submitBtn = document.getElementById("reserve-submit");
  var EMAIL = /^[^\s@]+@[^\s@]+[.][^\s@]{2,}$/;

  if (!form || !emailInput || !feedback) {
    return;
  }

  function showMessage(state, text) {
    feedback.className = "form-feedback" + (state ? " " + state : "");
    feedback.textContent = text;
    emailInput.setAttribute("aria-invalid", state === "error" ? "true" : "false");
  }

  function validateValue(value) {
    if (value === "") {
      showMessage("error", "Add an email address so we know where to write.");
      return false;
    }
    if (!EMAIL.test(value)) {
      showMessage("error", "That address looks unfinished \u2014 check the part after the @.");
      return false;
    }
    return true;
  }

  form.addEventListener("submit", function (event) {
    event.preventDefault();
    var value = emailInput.value.trim();
    if (!validateValue(value)) {
      emailInput.focus();
      return;
    }
    showMessage(
      "ok",
      "Reserved \u2014 Issue 14 will ship to " + value + ". Nothing was sent from this page, and you can cancel anytime."
    );
    emailInput.readOnly = true;
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.textContent = "Reserved";
    }
  });

  emailInput.addEventListener("input", function () {
    if (emailInput.readOnly) {
      return;
    }
    if (feedback.classList.contains("error")) {
      var value = emailInput.value.trim();
      if (EMAIL.test(value)) {
        showMessage("", "Looks like a complete address \u2014 reserve it.");
      } else if (value === "") {
        showMessage("", "");
      }
    }
  });

  emailInput.addEventListener("blur", function () {
    if (emailInput.readOnly) {
      return;
    }
    var value = emailInput.value.trim();
    if (value !== "") {
      validateValue(value);
    }
  });
})();

